--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_ASSESSMENT_BK__K0)) as HUB_ASSESSMENT_HK,
        MEDIUSINSURABILITY_SCORE as SCORE_VALUE,
        MEDIUSRISK_CLASS as SCORE_BAND,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_ASSESSMENT_K0__EMIT
    union all
    select
        md5(upper(HUB_ASSESSMENT_BK__K0)) as HUB_ASSESSMENT_HK,
        MEDIUSINSURABILITY_SCORE as SCORE_VALUE,
        null::varchar as SCORE_BAND,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_pv') }}
    where HUB_ASSESSMENT_K0__EMIT
)), hashed as (select *,
        case when SCORE_VALUE is not null or SCORE_BAND is not null
             then md5(upper(coalesce(SCORE_VALUE::varchar,'') || '||' || coalesce(SCORE_BAND::varchar,'')))
        end as SAT_ASSESSMENT_RISK_SCORING_HASHDIFF
    from feeders)

select * from hashed
where HUB_ASSESSMENT_HK is not null
  and SAT_ASSESSMENT_RISK_SCORING_HASHDIFF is not null
